import{_ as p,l as m,o as e,c as i,v as r,p as n,x as t,d as s,i as l,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"反向映射 rmap","description":"","frontmatter":{"title":"反向映射 rmap","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rmap.md","filePath":"cs/rmap.md","lastUpdated":1789023840000}'),d={name:"cs/rmap.md"};function _(h,a,u,f,A,E){const o=m("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="反向映射-rmap" tabindex="-1">反向映射 rmap <a class="header-anchor" href="#反向映射-rmap" aria-label="Permalink to &quot;反向映射 rmap&quot;">​</a></h1><div class="epigraph"><p>正向页表从虚址找到页框；反向映射从页框找到所有 pte，回收、迁移、unmap 才知道该拆哪几条翻译。</p><footer>—— 据 Gorman, <em>Understanding the Linux Virtual Memory Manager</em>；Bovet and Cesati 对对象反查的整理</footer></div><p><a href="/cs/socket-options">上一课</a>收口网络。虚存主干已有 <a href="/cs/demand-paging">分页</a> 与 <a href="/cs/tlb-shootdown">TLB</a>。缺口是 <strong>rmap</strong>：物理页上的「谁映射了我」，否则 shrinker 无法对匿名页与文件页做 try_to_unmap。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一页可被父进程、子进程、<a href="/cs/ksm">KSM</a> 合并者、多个 vma 同时映射。回收要：清 pte、打 TLB、必要时换出。没有反查只能扫所有进程页表——不可行。缺口：匿名页用 <code>anon_vma</code> 树串 vma；文件页用 <code>address_space</code> 的 i_mmap 树。本课不把锁的全部层级写成死锁论文。</p><p><span class="marginnote">fork 后 COW 页仍共享页框，rmap 条目变多。unmap 文件时走 i_mmap。对象是「页框 → pte 集合」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>缺页安装 pte 时：把 vma 挂到 anon_vma 或 interval tree。回收：<code>try_to_unmap</code> 遍历 rmap，把 pte 改成 swap/file 项，<code>tlb_flush</code>。<a href="/cs/page-cache">页缓存</a> 的文件页同样经 i_mmap 找到 mmap 了该文件的进程。对照 <a href="/cs/skbuff">sk_buff</a> 的引用计数：一个是包，一个是页框映射。</p>',8)),(e(),n(c,null,{default:t(()=>[l(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PFN%5B%22%E9%A1%B5%E6%A1%86%22%5D%20--%3E%20AV%5B%22anon_vma%20%E6%88%96%20i_mmap%22%5D%0A%20%20AV%20--%3E%20VMA%5B%22%E5%90%84%20vma%22%5D%0A%20%20VMA%20--%3E%20PTE%5B%22%E9%A1%B5%E8%A1%A8%E9%A1%B9%22%5D%0A%20%20PTE%20--%3E%20UNMAP%5B%22%E5%9B%9E%E6%94%B6%E6%97%B6%E6%8B%86%E9%99%A4%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>rmap 让「物理内存是共享资源」可执行：回收不必知道进程号先验。它是后课迁移、THP 拆页、mlock 会计的底座。不要写成数据库二级索引课，虽然结构都是反查。与 <a href="/cs/rdma-os">RDMA</a> 钉页：钉住的页 rmap 仍在，但不能换出。</p><p>fork 复杂度与 rmap 锁是可伸缩痛点，实现用锁分段。</p><p>实现上：anon_vma 锁是回收路径的热点，锁分段与批量 unmap 都为这个。KSM 合并后 rmap 更长，try_to_unmap 更贵。文件截断走 i_mmap，要和页锁交织。 读法上只引用<a href="/cs/socket-options">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>反向映射 rmap</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 device-exclusive 等特殊 rmap。不保证 32 位高内存的每条路径。下一课利用 rmap 把页搬走：迁移与 compaction。</p><p>版本字段会变，课序钉的是机制对象「反向映射 rmap」，不是某一主线内核的结构体名。 后课默认：页框能反查到所有 pte。为了凑大页或离线内存而搬家，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>rmap 从页框走到 pte；回收依赖它。</li><li>匿名走 anon_vma，文件走 i_mmap。</li><li>页迁移与 compaction 是下一课。</li><li>出处：Gorman <em>ULVMM</em>；Bovet <em>ULK</em>；Linux mm。</li></ul>',11))])}const k=p(d,[["render",_]]);export{T as __pageData,k as default};
